#!/usr/bin/env python3
"""Tạo lại HTML tĩnh và bản offline. Chỉ cần Python 3, không cần npm."""
import json,pathlib,re,html,base64,zipfile,sys
R=pathlib.Path(__file__).resolve().parents[1]
def load(n):return json.loads((R/'data'/f'{n}.json').read_text())
B=load('brand');P=load('products');S=load('services');J=load('projects');A=load('articles');C=load('categories');I=load('image-briefs'); ACTUAL=load('images-manifest'); ALIASES=load('image-aliases')
IM={x['path']:x for x in ACTUAL};CN={x['slug']:x['name'] for x in C};URL=B['siteUrl'].rstrip('/')+'/'
E=lambda x:html.escape(str(x),quote=True)
icons={'arrow':'<path d="M4 12h16m-6-6 6 6-6 6"/>','search':'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>','heart':'<path d="M20.5 4.6a5.5 5.5 0 0 0-8.5 1 5.5 5.5 0 0 0-8.5-1c-3 3-.7 7 2 9.5L12 20l6.5-5.9c2.7-2.5 5-6.5 2-9.5Z"/>','menu':'<path d="M3 6h18M3 12h18M3 18h18"/>','close':'<path d="m5 5 14 14M5 19 19 5"/>','chat':'<path d="M21 11.5a9 9 0 0 1-9 9 10 10 0 0 1-4-.8L3 21l1.2-5a9 9 0 1 1 16.8-4.5Z"/><path d="M8 9h8M8 13h5"/>','home':'<path d="m3 10 9-7 9 7M5 9v12h14V9M9 21v-8h6v8"/>','compass':'<circle cx="12" cy="12" r="9"/><path d="m16 8-3 5-5 3 3-5Z"/>','layers':'<path d="m12 3 10 6-10 6L2 9Zm-9 11 9 5 9-5M3 18l9 5 9-5"/>'}
def icon(n):return '<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">'+icons.get(n,icons['arrow'])+'</svg>'
def link(route,label,cl='',extra=''):return f'<a href="@@/{route}index.html" class="{cl}" {extra}>{label}</a>'
def btn(route,label,cl=''):return link(route,E(label)+' <span aria-hidden="true">↗</span>','btn '+cl)
def img(path,alt=None,cl='',eager=False,attrs=''):
 path=ALIASES.get(path,path);m=IM.get(path,{});w=m.get('width',1280);h=m.get('height',853)
 return f'<img src="@@/{path}" data-asset="{path}" alt="{E(alt or m.get("alt","Ý tưởng nội thất tham khảo"))}" width="{w}" height="{h}" class="{cl}" loading="{"eager" if eager else "lazy"}" decoding="async" {"fetchpriority=high" if eager else ""} {attrs}>'
def logo():return link('','<span class="monogram">T68</span><small>NỘI THẤT SÀI GÒN<span>T68 INTERIOR</span></small>','logo','aria-label="T68 Interior — Trang chủ"')
def header(route):
 nav=''.join(link(r,t,'active' if r and route.startswith(r) else '') for r,t in [('gioi-thieu/','Giới thiệu')])
 nav+='<button id="product-menu" class="menu-trigger" aria-expanded="false" aria-controls="mega-menu">Sản phẩm <span aria-hidden="true">⌄</span></button>'
 mega='<div id="mega-menu" class="mega" hidden><div class="wrap mega-grid"><div class="mega-intro"><span class="eyebrow">Bộ sưu tập</span><h3>Chọn theo<br>không gian sống.</h3>'+link('san-pham/','Tất cả mẫu nội thất →')+'</div>'
 for i in range(0,8,2):mega+='<div>'+''.join(link('san-pham/'+c['slug']+'/',c['name']) for c in C[i:i+2])+'</div>'
 mega+='</div></div>'
 nav+=mega+''.join(link(r,t,'active' if route.startswith(r) else '') for r,t in [('dich-vu/','Dịch vụ'),('du-an/','Không gian'),('blog/','Cẩm nang'),('lien-he/','Liên hệ')])
 return '<a class="skip" href="#main">Đến nội dung chính</a><div class="topbar"><div class="wrap"><span>TINH TẾ TRONG THIẾT KẾ · GIÁ TRỊ TRONG TỪNG KHÔNG GIAN</span><span class="right">'+link('faq/','Hỗ trợ & câu hỏi thường gặp')+'</span></div></div><header class="header"><div class="wrap header-inner">'+logo()+'<nav class="nav" id="main-nav" aria-label="Điều hướng chính">'+nav+'</nav><div class="header-actions"><button class="icon-btn" data-open-search aria-label="Tìm kiếm">'+icon('search')+'</button>'+link('yeu-thich/',icon('heart'),'icon-btn saved-launch','aria-label="Mẫu đã lưu"')+btn('lien-he/','Nhận tư vấn')+'<button id="mobile-menu" class="icon-btn mobile-toggle" aria-expanded="false" aria-controls="main-nav" aria-label="Mở menu">'+icon('menu')+'</button></div></div></header>'
def cta():return '<section class="cta"><div class="wrap"><div><span class="eyebrow">Bắt đầu câu chuyện của bạn</span><h2>Một không gian đẹp.<br>Một khởi đầu từ sự thấu hiểu.</h2></div>'+btn('lien-he/','Chia sẻ nhu cầu của bạn','white')+'</div></section>'
def footer():
 return '<footer class="footer"><div class="wrap"><div class="footer-grid"><div>'+logo()+'<p>Khám phá những giải pháp nội thất hài hòa giữa công năng, thẩm mỹ và dấu ấn cá nhân.</p><p>Hình ảnh và mẫu thiết kế trên website là ý tưởng tham khảo, chưa phải danh mục hàng hay công trình đã được xác nhận.</p></div><div><h4>KHÁM PHÁ T68</h4>'+''.join(link(r,t) for r,t in [('gioi-thieu/','Về T68'),('san-pham/','Mẫu nội thất'),('du-an/','Ý tưởng không gian'),('blog/','Cẩm nang'),('yeu-thich/','Mẫu bạn đã lưu')])+'</div><div><h4>GIẢI PHÁP NỘI THẤT</h4>'+''.join(link('dich-vu/'+s['slug']+'/',s['name']) for s in S[:4])+'</div><div><h4>KẾT NỐI & HỖ TRỢ</h4>'+link('lien-he/','Chuẩn bị yêu cầu tư vấn ↗')+link('faq/','Câu hỏi thường gặp')+link('bao-mat/','Thông tin bảo mật')+link('dieu-khoan/','Điều khoản sử dụng')+link('sitemap/','Sơ đồ website')+'</div></div><div class="footer-bottom"><span>© <span data-year>2026</span> NỘI THẤT T68 SÀI GÒN</span><span>Được tạo nên từ cảm hứng sống tinh tế.</span></div></div></footer>'
def overlays():
 return '''<div class="floating"><button class="backtop" id="backtop" aria-label="Trở lại đầu trang">↑</button><button class="chat-launch" id="chat-launch" aria-expanded="false" aria-controls="chat-panel">'''+icon('chat')+'''<span>Hỗ trợ tư vấn</span></button></div><aside class="chat-panel" id="chat-panel" aria-label="Trợ lý hướng dẫn T68" hidden><div class="chat-head"><div><strong>T68 · Đồng hành cùng bạn</strong><small>Hướng dẫn tự động theo kịch bản</small></div><button id="chat-close" aria-label="Đóng hỗ trợ">×</button></div><div class="chat-body"><div id="chat-answer" class="chat-answer" aria-live="polite">Chào bạn! Bạn đang tìm ý tưởng cho không gian nào? Chọn một chủ đề để bắt đầu.</div><div class="chat-options"><button data-chat="design">Tư vấn thiết kế</button><button data-chat="product">Tìm sản phẩm</button><button data-chat="material">Chọn vật liệu</button><button data-chat="quote">Yêu cầu báo giá</button><button data-chat="contact">Liên hệ</button></div><a id="chat-link" hidden></a></div></aside><dialog class="dialog" id="search-dialog"><div class="dialog-head"><h2>Bạn đang tìm điều gì?</h2><button class="icon-btn" data-close-dialog aria-label="Đóng tìm kiếm">'''+icon('close')+'''</button></div><div class="dialog-body"><label for="global-search" class="sr-only">Tìm sản phẩm, dịch vụ, bài viết</label><input id="global-search" class="field" type="search" placeholder="Thử tìm: sofa, Japandi, phòng bếp…" autocomplete="off"><div id="search-results" class="search-results" aria-live="polite"></div></div></dialog><dialog class="dialog lightbox" id="lightbox"><div class="dialog-head"><span>Ý tưởng thiết kế tham khảo</span><button class="icon-btn" data-close-dialog aria-label="Đóng ảnh">'''+icon('close')+'''</button></div><img id="zoom-image" alt=""><p id="zoom-caption"></p></dialog><dialog class="dialog" id="share-dialog"><div class="dialog-head"><h2>Chia sẻ liên kết</h2><button class="icon-btn" data-close-dialog aria-label="Đóng chia sẻ">'''+icon('close')+'''</button></div><div class="dialog-body"><label for="share-url">Sao chép địa chỉ dưới đây (website chỉ truy cập được sau khi được xuất bản).</label><input id="share-url" class="field" readonly></div></dialog><div id="toast" class="toast" role="status" hidden></div>'''
def section(content,cl=''):return '<section class="section '+cl+'"><div class="wrap">'+content+'</div></section>'
def head(ey,h,route=None,label='Xem tất cả'):
 return '<div class="section-head"><div><span class="eyebrow">'+ey+'</span><h2>'+h+'</h2></div>'+(link(route,label+' <span class="arrow" aria-hidden="true">↗</span>','text-link') if route is not None else '')+'</div>'
def top(title,desc,trail=None):
 trail=trail or []
 bread=link('','Trang chủ')+''.join('<span aria-hidden="true">/</span>'+link(r,E(n)) for r,n in trail)+'<span aria-hidden="true">/</span><span aria-current="page">'+E(title)+'</span>'
 return '<section class="page-top"><div class="wrap"><nav class="breadcrumbs" aria-label="Đường dẫn">'+bread+'</nav><h1>'+E(title)+'</h1><p>'+E(desc)+'</p></div></section>'
def product(p,attrs=True):
 data=' '.join(f'data-{k}="{E(v)}"' for k,v in [('product',p['id']),('name',p['name']),('category',p['category']),('style',p['style']),('material',p['material'])]) if attrs else ''
 return f'<article class="product-card" {data}><div class="product-photo">'+link('san-pham/'+p['slug']+'/',img(p['image']))+f'<button class="save" data-save="{p["id"]}" data-name="{E(p["name"])}" aria-label="Lưu {E(p["name"])}" aria-pressed="false">'+icon('heart')+'</button><span class="tag">Mẫu ý tưởng</span></div><p class="meta">'+CN[p['category']]+' / '+p['style']+'</p><h3>'+link('san-pham/'+p['slug']+'/',E(p['name']))+'</h3><p class="price">Liên hệ báo giá <span aria-hidden="true">↗</span></p></article>'
def concept(p):return '<article class="concept-card" data-project-category="'+E(p['category'])+'"><div class="img-wrap">'+link('du-an/'+p['slug']+'/',img(p['image']))+'</div><p class="meta">'+E(p['category'])+' · '+E(p['style'])+' / Ý tưởng tham khảo</p><h3>'+link('du-an/'+p['slug']+'/',E(p['name'])+' <span class="arrow">↗</span>')+'</h3></article>'
def article(a):return '<article class="blog-card" data-blog-category="'+E(a['category'])+'">'+link('blog/'+a['slug']+'/',img(a['image']))+'<p class="meta">'+E(a['category'])+' · Biên soạn 02.11.2026</p><h3>'+link('blog/'+a['slug']+'/',E(a['name']))+'</h3><p>'+E(a.get('intro','Những gợi ý thiết thực để lựa chọn và sắp xếp không gian sống.'))+'</p></article>'
FAQ=[('Cần chuẩn bị gì trước khi trao đổi thiết kế?','Bạn có thể chuẩn bị mặt bằng, ảnh hiện trạng, diện tích, số người sử dụng và một vài hình ảnh yêu thích. Ghi rõ những bất tiện hiện tại sẽ giúp cuộc trao đổi tập trung hơn.'),('Các mẫu trên website có phải sản phẩm đang bán?','Chưa. Các mẫu được trình bày dưới dạng ý tưởng tham khảo. Khả năng sản xuất, cấu tạo, kích thước, vật liệu và giá cần được xác nhận trong từng yêu cầu cụ thể.'),('Vì sao website chưa hiển thị giá cố định?','Chi phí phụ thuộc kích thước, cấu tạo, vật liệu, phụ kiện và phạm vi công việc. Website chưa có bảng giá được xác nhận, vì vậy không đưa giá ước đoán hoặc khuyến mãi.'),('Bao lâu có thể nhận được phương án và báo giá?','Thời gian phản hồi cần được thống nhất trực tiếp sau khi xác nhận kênh liên hệ và thông tin yêu cầu. Website không đặt cam kết thời gian khi chưa có dữ liệu doanh nghiệp.'),('Tải phiếu tư vấn có đồng nghĩa đã gửi yêu cầu?','Không. Tải phiếu chỉ lưu một tệp trên máy của bạn. Khi email được cấu hình, bạn cần tự gửi thư trong ứng dụng email. Khi dịch vụ nhận biểu mẫu được cấu hình, website chỉ thông báo tiếp nhận sau phản hồi thành công.'),('Ảnh có thể khác sản phẩm thực tế không?','Có. Toàn bộ hình ảnh hiện là hình ý tưởng được tạo riêng, không phải ảnh chụp hàng hóa hoặc công trình đã hoàn thành. Hãy đối chiếu mẫu vật liệu, bản vẽ và thông số được xác nhận trước khi quyết định.'),('T68 có chính sách bảo hành như thế nào?','Chưa có chính sách bảo hành được cung cấp cho website. Phạm vi, điều kiện và thời gian bảo hành cần được xác nhận bằng văn bản cho từng giao dịch.'),('Danh sách mẫu đã lưu nằm ở đâu?','Danh sách được lưu cục bộ trong trình duyệt của bạn, nếu trình duyệt cho phép. Dữ liệu này không tự đồng bộ sang thiết bị khác. Bạn có thể xóa toàn bộ tại trang Mẫu đã lưu.')]
def faqs(limit=8):return ''.join('<details class="accordion"><summary>'+E(q)+'</summary><p>'+E(a)+'</p></details>' for q,a in FAQ[:limit])
steps=[('Lắng nghe nhu cầu','Ghi lại ưu tiên về công năng, thẩm mỹ và ngân sách dự kiến.'),('Tư vấn hướng đi','Thảo luận bố cục, phong cách và các hạng mục cần giải quyết.'),('Khảo sát & thiết kế','Đối chiếu hiện trạng để phát triển phương án phù hợp.'),('Thống nhất giải pháp','Làm rõ vật liệu, cấu tạo, chi phí và phạm vi thực hiện.'),('Triển khai thi công','Tổ chức các hạng mục theo hồ sơ và kế hoạch được xác nhận.'),('Nghiệm thu & bàn giao','Kiểm tra hoàn thiện, ghi nhận và hướng dẫn sử dụng.')]
def process():return '<div class="process">'+''.join(f'<div class="step"><span>0{i+1}</span><h3>{n}</h3><p>{d}</p></div>' for i,(n,d) in enumerate(steps))+'</div><p class="note">Quy trình đề xuất để tham khảo; phạm vi và cách thực hiện cần được T68 xác nhận cho từng yêu cầu.</p>'
def category_card(c,i):
 path=[I[0]['path'],I[6]['path'],I[5]['path'],I[7]['path'],S[5]['image'],P[30]['image'],P[32]['image'],P[34]['image']][i]
 return link('san-pham/'+c['slug']+'/',img(path)+'<div class="space-label"><div><small>0'+str(i+1)+' / KHÔNG GIAN</small><h3>'+c['name']+'</h3></div><span class="arrow">↗</span></div>','space-card')
def home():
 hero='<section class="hero">'+img(I[0]['path'],cl='hero-image',eager=True,attrs='id="hero-image"')+'<div class="wrap hero-content"><span class="eyebrow">NỘI THẤT T68 SÀI GÒN</span><h1 id="hero-title">Kiến tạo không gian sống<br><em>mang dấu ấn riêng.</em></h1><p id="hero-desc">Tinh tế trong thiết kế. Hài hòa trong từng trải nghiệm. Khám phá những gợi ý nội thất dành cho tổ ấm của bạn.</p><div class="btnrow">'+btn('du-an/','Khám phá không gian','white')+btn('lien-he/','Nhận tư vấn thiết kế','outline')+'</div></div><div class="wrap hero-bottom"><span class="hero-note">CẢM HỨNG SỐNG ĐƯƠNG ĐẠI<br>Hình ý tưởng thiết kế tham khảo</span><div class="slide-controls"><button data-slide="-1" aria-label="Ảnh trước">←</button><span id="slide-count" class="slide-count" aria-live="polite">01 / 03</span><button data-slide="1" aria-label="Ảnh tiếp theo">→</button></div></div></section>'
 hero+='<div class="pillars"><div class="wrap pillar-row">'+''.join('<div>'+icon(ic)+'<div><strong>'+t+'</strong><small>'+d+'</small></div></div>' for ic,t,d in [('compass','Thiết kế có chủ đích','Bắt đầu từ nhu cầu của bạn'),('layers','Hài hòa từng chi tiết','Công năng đi cùng thẩm mỹ'),('home','Không gian mang dấu ấn riêng','Gợi mở cách sống bạn yêu')])+'</div></div>'
 about='<div class="split"><div class="split-image">'+img(I[3]['path'])+'</div><div class="split-copy"><span class="eyebrow">Về T68 Interior</span><h2>Không chỉ là nội thất.<br>Đó là cách bạn sống.</h2><p>Mỗi tổ ấm có một nhịp sống riêng. T68 hướng tới những không gian được tổ chức từ thói quen, cảm xúc và nhu cầu thực tế của người sử dụng.</p><p>Từ một góc đọc sách đến toàn bộ căn nhà, sự tinh tế bắt đầu ở tỷ lệ vừa vặn, chất liệu hài hòa và những chi tiết có lý do để hiện diện.</p><div class="quote">“Tinh tế trong thiết kế —<br>giá trị trong từng không gian.”</div>'+link('gioi-thieu/','Câu chuyện & định hướng T68 <span class="arrow">↗</span>','text-link')+'</div></div>'
 spaces=head('Những khoảng riêng của bạn','Cảm hứng cho từng không gian','san-pham/','Khám phá tất cả')+'<div class="grid cols-4">'+''.join(category_card(c,i) for i,c in enumerate(C[:4]))+'</div>'
 services=head('Từ ý tưởng đến không gian','Giải pháp theo cách bạn cần','dich-vu/','Tất cả dịch vụ')+'<div class="grid cols-3">'+''.join('<article class="service-card"><span class="number">0'+str(i+1)+'</span><h3>'+s['name']+'</h3><p>'+s['description']+'</p>'+link('dich-vu/'+s['slug']+'/','Tìm hiểu giải pháp <span class="arrow">↗</span>','text-link')+'</article>' for i,s in enumerate([S[0],S[1],S[7]]))+'</div>'
 products=head('Bộ sưu tập gợi ý','Những thiết kế đáng lưu lại','san-pham/','Xem bộ sưu tập')+'<div class="grid cols-4">'+''.join(product(P[i],False) for i in [0,3,8,18])+'</div><p class="note">Mẫu ý tưởng tham khảo. Vật liệu, thông số và khả năng cung cấp cần được xác nhận.</p>'
 philosophy='<div class="split"><div><span class="eyebrow">Triết lý thiết kế</span><h2>Đủ tinh giản để thở.<br>Đủ tinh tế để nhớ.</h2><p class="sub">Chúng tôi hướng đến sự cân bằng giữa công năng và cảm xúc. Ánh sáng làm dịu không gian. Chất liệu tạo chiều sâu. Tỷ lệ giúp mọi thứ trở nên vừa vặn.</p><div class="btnrow">'+btn('gioi-thieu/','Khám phá triết lý','outline')+'</div></div>'+img(I[4]['path'])+'</div>'
 concepts=head('Không gian & ý tưởng','Những câu chuyện được gợi mở','du-an/','Xem các ý tưởng')+'<div class="tabs"><button class="chip active" data-project-filter="" aria-pressed="true">Tất cả</button>'+''.join('<button class="chip" data-project-filter="'+c+'" aria-pressed="false">'+c+'</button>' for c in ['Căn hộ','Nhà phố','Biệt thự'])+'</div><div class="grid cols-2">'+''.join(concept(j) for j in J[:4])+'</div>'
 materials=head('Cảm nhận bằng chất liệu','Mộc mạc, nhưng không đơn điệu','blog/','Đọc cẩm nang')+'<p class="sub">Bắt đầu với một bảng màu vừa đủ. Quan sát mẫu thật dưới ánh sáng của căn phòng trước khi đưa ra lựa chọn.</p><div class="materials">'+''.join('<div class="material"><div class="swatch">'+img(I[n]['path'])+'</div><h3>'+t+'</h3><p>'+d+'</p></div>' for n,t,d in [(4,'Sắc gỗ ấm','Gợi chiều sâu và cảm giác gần gũi.'),(100,'Vải & sắc trung tính','Làm mềm đường nét kiến trúc.'),(104,'Bề mặt khoáng','Tạo điểm nhấn bằng vân và bóng đổ.'),(106,'Ánh sáng nhiều lớp','Cân bằng giữa dùng việc và thư giãn.')])+'</div>'
 blog=head('Cẩm nang sống đẹp','Một chút hiểu biết. Nhiều cảm hứng.','blog/','Tất cả bài viết')+'<div class="grid cols-3">'+''.join(article(a) for a in A[:3])+'</div>'
 faq='<div class="faq-grid"><div><span class="eyebrow">Giải đáp cùng bạn</span><h2>Trước khi bắt đầu<br>một không gian mới.</h2><p class="sub">Những điều cần biết để chuẩn bị cho cuộc trao đổi đầu tiên.</p>'+link('faq/','Xem thêm câu hỏi <span class="arrow">↗</span>','text-link')+'</div><div>'+faqs(4)+'</div></div>'
 return hero+section(about)+section(spaces,'cream')+section(services)+section(products,'cream')+section(philosophy,'philosophy')+section(concepts)+section(head('Cùng bạn từng bước','Từ cuộc trò chuyện đầu tiên')+process(),'bluegray')+section(materials,'cream')+section(blog)+section(faq,'cream')+cta()

def catalog(title='Mẫu nội thất',desc='Khám phá 42 gợi ý thiết kế cho từng góc nhà. Lưu lại mẫu bạn thích để chuẩn bị cho cuộc trao đổi về không gian của riêng mình.',items=None,cat='',saved=False):
 items=P if items is None else items
 opts=lambda values,first: '<option value="">'+first+'</option>'+''.join('<option value="'+E(v)+'">'+E(v)+'</option>' for v in values)
 catopts='<option value="">Mọi không gian</option>'+''.join('<option value="'+c['slug']+'" '+('selected' if cat==c['slug'] else '')+'>'+c['name']+'</option>' for c in C)
 filters='<aside class="filter-box"><h3>Tìm thiết kế phù hợp</h3><div><label for="filter-query">Tên mẫu</label><input class="field" data-filter id="filter-query" type="search" placeholder="Ví dụ: sofa"></div><div><label for="filter-category">Không gian</label><select class="field" data-filter id="filter-category">'+catopts+'</select></div><div><label for="filter-style">Phong cách</label><select class="field" data-filter id="filter-style">'+opts(sorted(set(p['style'] for p in P)),'Mọi phong cách')+'</select></div><div><label for="filter-material">Vật liệu gợi ý</label><select class="field" data-filter id="filter-material">'+opts(sorted(set(p['material'] for p in P)),'Mọi định hướng')+'</select></div><button class="btn light" id="reset-filters">Xóa bộ lọc</button></aside>'
 body='<div class="catalog">'+filters+'<div><div class="catalog-top"><span id="result-count" role="status">'+str(len(items))+' mẫu tham khảo</span><label class="sr-only" for="filter-sort">Sắp xếp</label><select class="field" id="filter-sort" data-filter><option value="name">Tên: A → Z</option><option value="name-desc">Tên: Z → A</option></select></div><div class="grid cols-3" data-catalog>'+''.join(product(p) for p in items)+'<div class="empty" id="catalog-empty" hidden><h3>Chưa có mẫu phù hợp</h3><p>Thử đổi từ khóa, xóa bộ lọc hoặc lưu một mẫu bạn thích.</p>'+link('san-pham/','Khám phá bộ sưu tập →','text-link')+'</div></div><nav class="pagination" id="pagination" aria-label="Trang kết quả"></nav><p class="note">Phong cách và vật liệu là định hướng ý tưởng. Chưa có giá, thông số hoặc vật liệu hàng hóa được xác minh.</p>'+('<button class="btn light" id="clear-saved">Xóa toàn bộ mẫu đã lưu</button>' if saved else '')+'</div></div>'
 quick='<div class="tabs tab-scroll">'+''.join(link('san-pham/'+k+'/',v,'chip') for k,v in [('sofa','Sofa'),('ban-tra','Bàn trà'),('ke-tivi','Kệ tivi'),('tu-giay','Tủ giày'),('giuong-ngu','Giường ngủ'),('tu-quan-ao','Tủ quần áo'),('ban-trang-diem','Bàn trang điểm'),('tu-bep','Tủ bếp'),('ban-an','Bàn ăn'),('ghe-an','Ghế ăn'),('ban-lam-viec','Bàn làm việc'),('tu-ho-so','Tủ hồ sơ'),('ke-trang-tri','Kệ trang trí'),('vach-ngan','Vách ngăn'),('combo-noi-that','Combo nội thất')])+'</div>'
 return top(title,desc)+section(quick+body)+cta()
def product_detail(p):
 related=[x for x in P if x['category']==p['category'] and x['id']!=p['id']][:3]
 gallery=[p]+related[:2]
 content=('<p class="inline-note">Hình cảm hứng dùng chung cho nhóm nội thất; mẫu này chưa có hình thiết kế riêng được xác nhận.</p><br>' if p.get('sharedIllustration') else '')+'<div class="detail-layout"><div><button class="gallery-main" data-zoom aria-label="Phóng to hình ý tưởng">'+img(p['image'],eager=True,attrs='id="gallery-image"')+'<span>Phóng to ⤢</span></button><div class="thumbs">'+''.join('<button class="'+('active' if i==0 else '')+'" data-thumb="'+x['image']+'" data-alt="'+E(x['name']+' — hình ý tưởng tham khảo')+'" aria-label="Xem '+E(x['name'])+'">'+img(x['image'])+'</button>' for i,x in enumerate(gallery))+'</div><p class="note">Ảnh chính và các gợi ý phối hợp cùng nhóm; không phải nhiều góc chụp của một sản phẩm thực.</p></div><div><span class="status">Mẫu ý tưởng tham khảo · '+p['id']+'</span><h1>'+E(p['name'])+'</h1><p>'+E(p['description'])+'</p><table class="specs"><tr><th>Không gian</th><td>'+CN[p['category']]+'</td></tr><tr><th>Phong cách gợi ý</th><td>'+p['style']+'</td></tr><tr><th>Định hướng vật liệu</th><td>'+p['material']+' — chưa xác minh cấu tạo</td></tr><tr><th>Kích thước & phụ kiện</th><td>Cần xác nhận theo phương án</td></tr><tr><th>Giá</th><td>Liên hệ báo giá</td></tr></table><div class="btnrow">'+link('lien-he/','Yêu cầu tư vấn mẫu này ↗','btn',f'data-request="{E(p["name"])}"')+f'<button class="btn light" data-save="{p["id"]}" data-name="{E(p["name"])}" aria-pressed="false">Lưu mẫu '+icon('heart')+'</button><button class="btn light" data-share>Chia sẻ ↗</button></div><p class="note">Chưa xác nhận tình trạng cung cấp. Không có giá bán, đánh giá hay cam kết bảo hành mặc định.</p></div></div>'
 content+='<div class="detail-copy"><h2>Đặt thiết kế vào không gian của bạn</h2><p>'+E(p['description'])+' Hãy đo vị trí dự kiến, ghi lại cửa mở, ổ cắm và hướng ánh sáng trước khi trao đổi. Một hình ảnh yêu thích là điểm khởi đầu; tỷ lệ và thói quen sử dụng mới quyết định cách bố trí.</p><h2>Những điều cần xác nhận</h2><ul><li>Kích thước hoàn thiện, khoảng thao tác và cách vận chuyển tới vị trí lắp đặt.</li><li>Mẫu vật liệu thực tế, màu hoàn thiện, cấu tạo bên trong và phụ kiện.</li><li>Phạm vi cung cấp, giá, lịch thực hiện và điều kiện bảo hành bằng văn bản.</li></ul><h2>Gợi ý chăm sóc bề mặt</h2><p>Vệ sinh theo hướng dẫn của vật liệu được xác nhận. Thử sản phẩm làm sạch ở vị trí khuất, tránh để chất lỏng đọng lâu và không dùng hóa chất mạnh khi chưa biết tính tương thích. Hình ảnh này không đủ để xác định loại bề mặt thực tế.</p></div>'
 bread='<nav class="breadcrumbs" aria-label="Đường dẫn">'+link('','Trang chủ')+' / '+link('san-pham/','Mẫu nội thất')+' / '+link('san-pham/'+p['category']+'/',CN[p['category']])+' / <span aria-current="page">'+E(p['name'])+'</span></nav>'
 return section(bread+content)+section(head('Cùng một cảm hứng','Gợi ý bạn có thể quan tâm')+'<div class="grid cols-3">'+''.join(product(x,False) for x in related)+'</div>','cream')+cta()

def projects():return top('Không gian & ý tưởng','Những hướng tiếp cận khác nhau cho cách sống của bạn. Toàn bộ nội dung dưới đây là ý tưởng thiết kế tham khảo, chưa phải công trình T68 đã thực hiện.')+section('<div class="tabs tab-scroll"><button class="chip active" data-project-filter="" aria-pressed="true">Tất cả</button>'+''.join('<button class="chip" data-project-filter="'+E(c)+'" aria-pressed="false">'+c+'</button>' for c in dict.fromkeys(j['category'] for j in J))+'</div><div class="grid cols-3">'+''.join(concept(j) for j in J)+'</div>')+cta()
def project_detail(j):
 rel=[x for x in J if x['category']==j['category'] and x['id']!=j['id']][:2]
 return top(j['name'],j['description'],[('du-an/','Ý tưởng không gian')])+section('<span class="status">Ý tưởng thiết kế tham khảo · '+j['style']+'</span><button class="gallery-main" data-zoom aria-label="Mở ảnh lớn">'+img(j['image'],eager=True,cl='page-intro-img')+'</button><div class="detail-copy"><p class="inline-note">Hình cảm hứng minh họa có thể được sử dụng cho nhiều bài ý tưởng; không đại diện cho một công trình riêng đã thực hiện.</p><h2>Ý tưởng tổ chức không gian</h2><p>'+j['description']+'</p><p>Thay vì bắt đầu bằng danh sách đồ cần mua, hãy xác định điểm nhìn chính và đường di chuyển hằng ngày. Những mảng đồ lớn được đặt trước, chi tiết trang trí được bổ sung sau để giữ sự cân bằng.</p><h2>Chất liệu, ánh sáng và nhịp sống</h2><p>Hình ảnh gợi một hướng phối màu và bề mặt; không xác nhận chủng loại vật liệu. Khi phát triển thiết kế, cần so sánh mẫu thật với ánh sáng, độ ẩm và cường độ sử dụng của từng vị trí.</p><p>Các thông tin như diện tích, địa điểm, chủ đầu tư, thời gian hay chi phí không được gán cho concept này vì chưa có hồ sơ công trình thực tế.</p><div class="btnrow">'+btn('lien-he/','Trao đổi về ý tưởng tương tự')+'<button class="btn light" data-share>Chia sẻ ý tưởng ↗</button></div></div>')+section(head('Mở rộng góc nhìn','Các hướng thiết kế cùng không gian')+'<div class="grid cols-2">'+''.join(concept(x) for x in rel)+'</div>','cream')+cta()

def service_index():return top('Giải pháp nội thất','Mỗi không gian bắt đầu từ một nhu cầu khác nhau. Khám phá các hướng dịch vụ và chuẩn bị thông tin cho cuộc trao đổi đầu tiên.')+section('<div class="grid cols-2">'+''.join('<article class="concept-card">'+link('dich-vu/'+s['slug']+'/',img(s['image']))+'<p class="meta">Hướng dịch vụ tham khảo</p><h3>'+link('dich-vu/'+s['slug']+'/',s['name']+' ↗')+'</h3><p class="sub">'+s['description']+'</p></article>' for s in S)+'</div>')+cta()
def service_detail(s,idx):
 points=[['Nhu cầu và phong cách','Mặt bằng công năng','Bảng màu và ý tưởng vật liệu','Hồ sơ cần bàn giao'],['Hồ sơ và hiện trạng','Cấu tạo, phụ kiện và mẫu duyệt','Thứ tự triển khai','Tiêu chí kiểm tra và nghiệm thu'],['Lối đi và lưu trữ','Khu vực chung và riêng','Hệ kỹ thuật hiện có','Quy định cải tạo của tòa nhà'],['Kết nối các tầng','Khoảng lấy sáng','Riêng tư và thông thoáng','Vận chuyển, thi công theo tầng'],['Tỷ lệ không gian lớn','Quan hệ trong nhà và cảnh quan','Khu vực tiếp khách và sinh hoạt riêng','Bảo trì và sử dụng dài hạn'],['Nhu cầu tập trung và trao đổi','Thiết bị, đường dây và lưu trữ','Âm học và ánh sáng','Khả năng thay đổi quy mô'],['Hành trình xem sản phẩm','Ánh sáng trưng bày','Khu vực trao đổi với khách','Kho và hoạt động vận hành'],['Phân loại phần cần giữ','Vấn đề công năng hiện tại','Hạng mục ưu tiên','Tác động tới sinh hoạt trong thời gian cải tạo']][idx]
 return top(s['name'],s['headline'],[('dich-vu/','Dịch vụ')])+section('<div class="split"><div>'+img(s['image'],eager=True)+'</div><div><span class="eyebrow">Giải pháp theo nhu cầu</span><h2>'+s['headline']+'</h2><p class="sub">'+s['description']+'</p><div class="btnrow">'+btn('lien-he/','Chuẩn bị yêu cầu tư vấn')+'</div><p class="note">Hướng dịch vụ giới thiệu để tham khảo. Phạm vi, khả năng tiếp nhận và chi phí cần được xác nhận trực tiếp.</p></div></div>')+section(head('Nội dung cần làm rõ','Những điểm bắt đầu quan trọng')+'<div class="grid cols-4">'+''.join('<div class="step"><span>0'+str(i+1)+'</span><h3>'+p+'</h3><p>Ghi lại hiện trạng và mong muốn để cùng đối chiếu khi phát triển phương án.</p></div>' for i,p in enumerate(points))+'</div>','cream')+section('<div class="detail-copy"><h2>Bạn nên chuẩn bị những gì?</h2><p>Gửi kèm mặt bằng hoặc bản vẽ hiện trạng nếu có, ảnh chụp đủ các hướng, loại không gian, diện tích và số người sử dụng. Một danh sách ngắn về điều đang bất tiện sẽ hữu ích hơn chỉ một bộ ảnh phong cách.</p><p>Hãy phân biệt hạng mục bắt buộc và mong muốn bổ sung. Ngân sách dự kiến cùng mốc thời gian mong muốn giúp xác định phạm vi trao đổi; đây chưa phải một báo giá hay cam kết triển khai.</p><h2>Từ phương án đến quyết định</h2><p>Trước khi thống nhất, cần xác nhận đầu việc, sản phẩm bàn giao, số lần điều chỉnh, loại vật liệu và các điều kiện thực hiện. Với hạng mục thi công, bản vẽ và mẫu hoàn thiện cần được đối chiếu cùng hiện trạng.</p></div>')+section(head('Hành trình tham khảo','Cùng bạn đi từng bước')+process(),'bluegray')+section('<div class="grid cols-2">'+img(I[80+idx]['path'])+img(I[88+idx]['path'])+'</div>')+cta()

PAGES={}
def add(route,title,desc,body,schema=None):PAGES[route]=dict(title=title+' | '+B['name'],description=desc,body=body,schema=schema or [])
def simple(title,desc,body):return top(title,desc)+section('<div class="legal">'+body+'</div>')
article_content=[
('Một chiếc sofa đẹp cần phù hợp với tỷ lệ phòng và cách bạn sử dụng mỗi ngày.',[
('Bắt đầu bằng lối đi','Đo không gian sử dụng thực tế, bao gồm cửa ra vào, hướng mở cửa và tuyến di chuyển tới các phòng. Đánh dấu kích thước sofa dự kiến trên sàn để hình dung phần diện tích còn lại. Đừng chọn chỉ từ số chỗ ngồi được ghi trong tên mẫu.'),
('Quan sát cách cả nhà sử dụng','Nếu thường trò chuyện cùng nhau, cách bố trí các chỗ ngồi hướng về nhau có thể quan trọng hơn kích thước màn hình. Nếu ưu tiên đọc sách hoặc nằm nghỉ, hãy thử độ sâu đệm, chiều cao tay vịn và điểm tựa lưng trên mẫu thật.'),
('Chọn cấu trúc trước màu sắc','Sofa thẳng giữ bố cục gọn; sofa góc tổ chức vùng ngồi rõ hơn; mô-đun cho phép thay đổi cách ghép nhưng cần kiểm tra điểm nối. Mỗi lựa chọn đều cần được đối chiếu với mặt bằng. Đường cong tạo cảm giác mềm nhưng không tự động giúp phòng rộng hơn.'),
('Kiểm tra vải dưới ánh sáng của nhà','Một màu kem có thể ngả xám hoặc vàng dưới nguồn sáng khác nhau. Xem mẫu vải lớn, cảm nhận bề mặt và hỏi rõ cách vệ sinh, cấu tạo đệm, khung và phần có thể tháo rời. Ảnh minh họa không đủ để xác nhận chất liệu.'),
('Trước khi chốt lựa chọn','Ghi lại kích thước tổng thể, kích thước sử dụng và đường vận chuyển. Thống nhất các thông số bằng văn bản cùng điều kiện giao, lắp đặt và bảo hành được bên cung cấp xác nhận.')]),
('Japandi gợi một không gian giản dị, ấm và chú trọng cách đồ vật phục vụ đời sống.',[
('Đặt công năng vào trung tâm','Thay vì bắt đầu bằng một danh sách đồ mang nhãn phong cách, hãy xác định khu vực cần nghỉ ngơi, lưu trữ và sinh hoạt. Giữ những món có vai trò rõ ràng, giảm các chi tiết khiến lối đi hoặc mặt bàn trở nên chật.'),
('Một bảng màu có chiều sâu','Sắc trắng ấm, be, xám dịu và gỗ sáng có thể làm nền. Thêm một điểm đậm nhỏ giúp tạo chiều sâu, nhưng không cần biến mọi bề mặt thành cùng một màu. Sự khác biệt của chất liệu thường đủ để tạo nhịp điệu.'),
('Cân bằng mềm và cứng','Vải, rèm và thảm làm mềm hình khối của bàn, tủ hay tường. Hãy quan sát tỷ lệ bề mặt thay vì chỉ phối từng món riêng lẻ. Một chiếc ghế mộc có thể nổi bật hơn khi quanh nó có đủ khoảng trống.'),
('Ánh sáng và sự tĩnh tại','Ưu tiên kiểm soát ánh sáng chói và tạo nguồn sáng phù hợp ở nơi đọc, làm việc hoặc nghỉ ngơi. Đèn trang trí nên đồng thời giải quyết một nhu cầu. Không cần phủ kín trần bằng nhiều điểm sáng giống nhau.'),
('Áp dụng có chọn lọc','Bạn không cần thay toàn bộ đồ đang dùng để tạo cảm giác bình yên. Bắt đầu bằng sắp xếp lại lưu trữ, giảm đồ trên bề mặt và thống nhất một vài chất liệu chính. Chọn phần phù hợp với thói quen gia đình.')]),
('Bảng màu trung tính trở nên thú vị nhờ sắc độ, bề mặt và cách ánh sáng di chuyển trong phòng.',[
('Phân biệt sắc ấm và sắc lạnh','Hai màu cùng được gọi là trắng có thể phản ứng khác nhau khi đặt cạnh gỗ hoặc đá. Đặt các mẫu cạnh nhau để xem sắc nền có xung đột không. Không nên quyết định dựa vào màn hình điện thoại.'),
('Tạo lớp bằng chất liệu','Vải thô, mặt sơn mịn, vân gỗ và bề mặt khoáng tạo cảm giác khác nhau dù gần cùng màu. Chọn một chất liệu chủ đạo và vài chất liệu hỗ trợ để tổng thể có trọng tâm.'),
('Dùng tương phản ở vị trí có chủ đích','Một chân đèn, khung tranh hay đường viền đậm có thể giúp không gian rõ nét hơn. Không cần chia đều điểm nhấn khắp phòng. Quan sát từ cửa vào để biết mắt đang bị kéo về đâu.'),
('Thử mẫu trong thời gian khác nhau','Xem bảng màu vào buổi sáng, chiều và khi bật đèn. Rèm, sàn và cảnh quan ngoài cửa cũng làm thay đổi cảm nhận. Nên thử trên diện tích đủ lớn trước khi hoàn thiện toàn bộ.'),
('Giữ chỗ cho đồ dùng cá nhân','Sách, tranh và vật kỷ niệm sẽ thêm màu sắc theo thời gian. Một nền trung tính có giá trị khi giúp những vật đó cùng tồn tại tự nhiên, thay vì yêu cầu mọi đồ vật phải đồng màu.')]),
('Tên vật liệu chưa đủ để quyết định. Điều cần làm rõ là cấu tạo, bề mặt và môi trường sử dụng.',[
('Hỏi về phần bên trong','Với một cánh tủ, hãy xác nhận vật liệu nền, cấu tạo cạnh và lớp phủ. Với gỗ tự nhiên, hỏi loại gỗ và cách hoàn thiện được đề xuất. Không suy ra chất lượng chỉ từ tên thương mại hoặc màu vân trên ảnh.'),
('Đối chiếu với vị trí sử dụng','Khu vực gần nước, chịu nắng, dùng thường xuyên hay ít sử dụng có yêu cầu khác nhau. Bàn làm việc, tủ phòng ngủ và tủ bếp không nên được đánh giá bằng một tiêu chí duy nhất.'),
('Xem mẫu thật và tài liệu','Yêu cầu mẫu bề mặt, mẫu cạnh và thông tin của nhà cung cấp. Nếu có tuyên bố về chống ẩm, độ bền hoặc phát thải, cần xem phạm vi kiểm tra và giấy tờ tương ứng. Không coi thuật ngữ quảng cáo là thông số kỹ thuật.'),
('Tính đến khả năng bảo trì','Hỏi cách vệ sinh, xử lý vết xước và thay thế chi tiết. Một bề mặt hợp với nhu cầu sử dụng và dễ bảo trì thường có ích hơn lựa chọn chỉ hấp dẫn ở lần nhìn đầu tiên.'),
('Ghi vào hồ sơ thống nhất','Tên vật liệu, mã màu, độ dày, cấu tạo và phụ kiện cần được xác nhận trong hồ sơ hoặc báo giá. Bài viết này cung cấp cách đặt câu hỏi, không xác nhận đặc tính của bất kỳ sản phẩm T68 nào.')]),
('Ánh sáng nên đi theo hoạt động trong phòng, từ sinh hoạt chung tới làm việc và nghỉ ngơi.',[
('Lập bản đồ các hoạt động','Ghi rõ nơi đọc sách, dùng máy tính, chuẩn bị bữa ăn và thư giãn. Mỗi hoạt động có vị trí quan sát khác nhau; đặt đèn dựa trên công việc giúp tránh tình trạng đủ sáng tổng thể nhưng thiếu sáng nơi cần.'),
('Kết hợp nhiều vai trò','Nguồn sáng nền tạo cảm giác chung, nguồn sáng tại chỗ hỗ trợ thao tác và ánh sáng nhấn làm rõ một chi tiết. Không nhất thiết cả ba phải bật cùng lúc. Hãy nghĩ tới các kịch bản sử dụng vào những thời điểm khác nhau.'),
('Kiểm soát chói và phản chiếu','Quan sát đèn từ vị trí ngồi, nằm và đứng. Màn hình, mặt kính hoặc bề mặt bóng có thể phản chiếu nguồn sáng. Thử vị trí, hướng chiếu và rèm trước khi thêm nhiều đèn hơn.'),
('Xem nhiệt độ màu cùng vật liệu','Ánh sáng tác động lên sắc gỗ, đá, sơn và vải. Nên thử phối nguồn sáng với mẫu vật liệu thay vì quyết định riêng từng phần. Các khu vực liên thông cần được xem cùng nhau.'),
('Thống nhất với hệ điện','Vị trí công tắc, ổ cắm, bộ điều khiển và yêu cầu thi công phải do người có chuyên môn kiểm tra. Bố trí thẩm mỹ cần đi cùng khả năng lắp đặt, sử dụng và bảo trì thực tế.')]),
('Một căn bếp thuận tiện bắt đầu từ thứ tự thao tác và những đồ bạn dùng thường xuyên.',[
('Đi theo một bữa ăn thực tế','Hãy thử mô tả từ lúc lấy thực phẩm đến rửa, sơ chế, nấu và dọn rửa. Ghi lại những lần phải quay lại hoặc đi cắt qua người khác. Đây là cách đơn giản để tìm điểm bất tiện trên mặt bằng.'),
('Đặt đồ theo tần suất sử dụng','Những món dùng hằng ngày nên ở nơi dễ tiếp cận. Đồ hiếm dùng có thể chuyển tới khoang xa hơn. Phân chia lưu trữ theo nhóm công việc giúp giảm việc mở nhiều ngăn để tìm một món.'),
('Dành mặt bàn để thao tác','Mặt bàn có thể bị chiếm bởi thiết bị nhỏ, giá gia vị và đồ trang trí. Hãy xác định vị trí cố định cho từng thiết bị, đồng thời giữ khoảng trống cần thiết bên khu rửa và nấu theo phương án chuyên môn.'),
('Kiểm tra cánh mở và lối đi','Mở thử các cánh tủ, ngăn kéo và thiết bị trên bản vẽ hoặc bằng cách đánh dấu hiện trường. Cần tính tình huống có nhiều người cùng sử dụng. Đảo bếp chỉ hữu ích khi không gây cản trở lưu thông.'),
('Xác nhận cấu tạo hoàn thiện','Vật liệu, phụ kiện, chống thấm tại vị trí cần thiết và hệ kỹ thuật phải được xác nhận theo thiết kế. Không suy ra tính năng từ màu sắc hoặc ảnh minh họa của một mẫu bếp.')]),
('Góc làm việc hiệu quả không cần nhiều đồ, nhưng cần phù hợp với công việc và cơ thể bạn.',[
('Chọn vị trí theo sự tập trung','Quan sát tiếng ồn, dòng người đi qua và ánh sáng trong thời gian làm việc. Vị trí đẹp trên ảnh chưa chắc phù hợp với các cuộc gọi hoặc nhu cầu tập trung của bạn.'),
('Sắp xếp theo nhóm việc','Để thiết bị, giấy tờ và dụng cụ đúng khu vực sử dụng. Dành một chỗ cất đồ khi kết thúc ngày làm việc để mặt bàn dễ trở về trạng thái gọn. Chỉ giữ trên bàn những gì cần tiếp cận nhanh.'),
('Thử bàn ghế trước khi chọn','Chiều cao, khoảng để chân và cách đặt màn hình cần phù hợp với người dùng. Hãy thử thực tế và điều chỉnh trong quá trình sử dụng. Một hình ảnh sản phẩm không thể xác nhận mức độ thoải mái.'),
('Ánh sáng và đường dây','Tránh vị trí đèn hoặc cửa gây phản chiếu khó chịu lên màn hình. Bố trí ổ cắm và đường dây có tổ chức; hệ điện cần được kiểm tra bởi người có chuyên môn. Đừng để dây dẫn cắt qua lối đi.'),
('Tạo một ranh giới nhẹ','Kệ thấp, thảm hoặc thay đổi hướng bàn có thể giúp phân biệt góc làm việc với nơi nghỉ. Chọn giải pháp có thể điều chỉnh khi nhu cầu thay đổi thay vì cố định quá nhiều cấu trúc.')]),
('Bàn ăn cần được chọn cùng ghế, lối đi và cách gia đình sử dụng căn phòng.',[
('Tính không gian khi ghế được kéo ra','Kích thước mặt bàn chỉ là một phần. Hãy xem người dùng có thể đứng lên, đi qua và tiếp cận chỗ ngồi thuận tiện không. Đánh dấu bố cục trên sàn giúp dễ nhận ra các điểm chật.'),
('Chọn hình dáng theo mặt bằng','Bàn tròn hỗ trợ trò chuyện, bàn dài có thể hợp phòng thuôn, còn bàn oval làm mềm hai đầu bố cục. Đây là gợi ý tổ chức; lựa chọn cuối cùng cần được thử với không gian thực tế.'),
('Ghép bàn và ghế như một bộ','Chiều cao mặt ghế, tay vịn và phần dưới bàn ảnh hưởng trực tiếp đến sử dụng. Thử tư thế ngồi và kiểm tra ghế có thể đẩy vào gọn không. Không chọn từng món chỉ vì đẹp riêng lẻ.'),
('Đặt ánh sáng theo khu vực dùng bữa','Đèn thả nên được xem cùng vị trí bàn và tầm nhìn khi ngồi. Ánh sáng cần hỗ trợ bữa ăn mà không gây chói. Kiểm tra cả khi nhìn từ phòng khách hoặc bếp nếu các không gian liên thông.'),
('Để bàn phục vụ nhiều khoảnh khắc','Ngoài dùng bữa, bàn có thể là nơi trò chuyện, đọc hoặc làm việc ngắn. Xem lại thói quen thực tế để chọn cấu tạo, mặt bàn và cách bảo quản phù hợp.')]),
('Có thể gợi tinh thần Indochine bằng một vài chi tiết có chọn lọc trong bố cục hiện đại.',[
('Chọn một điểm neo','Đó có thể là một chiếc ghế mây, hệ cửa hoặc mảng gạch họa tiết. Chọn một trọng tâm trước khi thêm các chi tiết khác giúp tổng thể không bị chia nhỏ.'),
('Giữ nền đủ thoáng','Sắc gỗ đậm và hoa văn tạo sức nặng thị giác. Cân bằng bằng tường sáng, ánh sáng tự nhiên và những khoảng trống. Không cần làm mọi món đồ đều mang cùng một mô-típ.'),
('Đối thoại giữa cũ và mới','Một hình khối đương đại có thể đi cùng chi tiết đan hoặc đường viền gợi nét thủ công. Điều cần quan sát là tỷ lệ, độ đậm nhạt và công năng của cả bố cục.'),
('Vật liệu cần phù hợp điều kiện sử dụng','Chi tiết tự nhiên hoặc thủ công có cách bảo trì riêng. Xem mẫu thật và hỏi rõ cấu tạo, hoàn thiện, độ phù hợp với vị trí sử dụng. Ảnh ý tưởng không thay thế thông tin của nhà cung cấp.'),
('Đưa cá tính vào có chừng mực','Tranh, gốm hoặc đồ kỷ niệm có thể tạo lớp ý nghĩa riêng. Ưu tiên những vật bạn muốn giữ lâu dài thay vì lấp đầy không gian bằng chi tiết chỉ cùng nhãn phong cách.')]),
('Một chiếc kệ đẹp cần có khoảng trống để đồ vật được nhìn thấy và dễ sử dụng.',[
('Chia nhóm thay vì rải đều','Gom sách, gốm hoặc vật kỷ niệm thành một vài cụm. Thử thay đổi chiều cao và hướng đặt để tạo nhịp, nhưng vẫn giữ mỗi nhóm có lý do hiện diện.'),
('Để khoảng trống làm việc','Không cần phủ kín tất cả các tầng. Khoảng trống giúp mắt nghỉ và làm nổi bật món đồ bạn muốn chú ý. Hãy quan sát kệ từ vị trí thường nhìn, không chỉ ở cự ly gần.'),
('Kết hợp lưu trữ kín','Những vật nhỏ dùng hằng ngày có thể được gom vào hộp hoặc khoang kín. Sự gọn gàng của tổng thể phụ thuộc vào chỗ cất đồ thực tế, không chỉ cách sắp vài món trang trí.'),
('Kiểm tra nền tường và cấu tạo','Với kệ treo, tải trọng, phụ kiện và loại tường cần được người có chuyên môn kiểm tra. Kệ đứng cần phương án phù hợp để hạn chế rủi ro đổ. Đừng suy ra khả năng chịu lực từ hình ảnh.'),
('Thay đổi theo nhịp sống','Kệ không cần hoàn thiện một lần rồi giữ nguyên. Có thể đổi vài cuốn sách, thêm một món gốm hoặc bớt đồ theo thời gian. Giữ sự linh hoạt giúp không gian gần với người sử dụng hơn.')])]
for a,(intro,parts) in zip(A,article_content):
 if 'intro' not in a:a['intro']=intro
 if 'sections' not in a:a['sections']=[dict(title=t,text=p) for t,p in parts]
(R/'data/articles.json').write_text(json.dumps(A,ensure_ascii=False,indent=2))

def article_detail(a):
 body='<p>'+E(a['intro'])+'</p>'+img(a['image'],eager=True)
 for i,s in enumerate(a['sections']):
  body+=f'<h2 id="phan-{i+1}">{E(s["title"])}</h2><p>{E(s["text"])}</p>'
  if i==2:body+=img(a['detailImage'])
 body+='<p class="note">Biên soạn ngày 02/11/2026. Nội dung gợi ý chung, không phải hồ sơ thiết kế hay thông số sản phẩm. Hình ảnh minh họa là ý tưởng tổng hợp.</p><div class="btnrow">'+btn('lien-he/','Chuẩn bị nhu cầu của bạn')+'<button class="btn light" data-share>Chia sẻ bài viết ↗</button></div>'
 sidebar='<aside class="sidebar"><h3>Trong bài viết này</h3>'+''.join(f'<a href="#phan-{i+1}">{E(s["title"])}</a>' for i,s in enumerate(a['sections']))+'</aside>'
 return top(a['name'],a['category']+' · Biên soạn 02/11/2026',[('blog/','Cẩm nang')])+section('<div class="article-layout"><article class="article-body">'+body+'</article>'+sidebar+'</div>')+section(head('Tiếp tục khám phá','Cảm hứng cho tổ ấm')+'<div class="grid cols-3">'+''.join(article(x) for x in [x for x in A if x!=a][:3])+'</div>','cream')

def contact():
 options=''.join('<option>'+c['name']+'</option>' for c in C)
