add('gioi-thieu/','Về T68 Interior','Triết lý và định hướng nội thất T68 Sài Gòn: thẩm mỹ, công năng và trải nghiệm sống.',top('Một không gian đẹp bắt đầu từ sự thấu hiểu.','NỘI THẤT T68 SÀI GÒN · Định hướng thương hiệu')+section('<div class="split">'+img(I[2]['path'],eager=True)+'<div><span class="eyebrow">Câu chuyện định hướng</span><h2>Chú tâm vào cách<br>bạn sống mỗi ngày.</h2><p class="sub">T68 hướng tới giải pháp nội thất có thẩm mỹ và phù hợp với nhu cầu sử dụng. Từ hình khối lớn đến những điểm chạm nhỏ, thiết kế được nhìn như một phần của đời sống.</p><p class="sub">Website giới thiệu định hướng thiết kế cùng các mẫu ý tưởng. Những dữ liệu như lịch sử thành lập, năng lực đã kiểm chứng, đội ngũ, địa chỉ hay hồ sơ dự án sẽ được bổ sung khi có thông tin chính thức.</p></div></div>')+section(head('Giá trị hướng tới','Những điều định hình một thiết kế')+'<div class="grid cols-3">'+''.join('<div class="step"><h3>'+t+'</h3><p>'+d+'</p></div>' for t,d in [('Lắng nghe trước khi vẽ','Tìm hiểu thói quen, mong muốn và điều đang bất tiện để đặt đúng bài toán thiết kế.'),('Cân bằng công năng & thẩm mỹ','Mỗi hình khối và bề mặt cần gắn với trải nghiệm sử dụng cụ thể.'),('Rõ ràng trong lựa chọn','Giúp việc trao đổi về phương án, vật liệu và phạm vi công việc trở nên dễ hiểu.')])+'</div>','cream')+section(head('Quy trình đề xuất','Từng bước phát triển không gian')+process())+cta())
