def jsonsafe(v):return json.dumps(v,ensure_ascii=False,separators=(',',':')).replace('</','<\\/')
def meta(r,p):
 canonical=URL+r;schema=[{'@type':'Organization','name':B['name'],'url':URL},{'@type':'WebSite','name':B['name'],'url':URL}]
 if r:schema.append({'@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':1,'name':'Trang chủ','item':URL},{'@type':'ListItem','position':2,'name':p['title'].split(' | ')[0],'item':canonical}]})
 schema+=p['schema'];robots='noindex,follow' if r in ['404/','yeu-thich/'] else 'index,follow'
 return '<title>'+E(p['title'])+'</title><meta name="description" content="'+E(p['description'])+'"><meta name="robots" content="'+robots+'"><link rel="canonical" href="'+E(canonical)+'"><meta property="og:locale" content="vi_VN"><meta property="og:type" content="website"><meta property="og:title" content="'+E(p['title'])+'"><meta property="og:description" content="'+E(p['description'])+'"><meta property="og:url" content="'+E(canonical)+'"><meta property="og:image" content="'+URL+I[0]['path']+'"><meta name="twitter:card" content="summary_large_image"><script type="application/ld+json">'+jsonsafe({'@context':'https://schema.org','@graph':schema})+'</script>'
